import{z as o,x as n,o as l,c as d,q as t,j as r,D as e,d as a,s as i,S as s,b as A}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"合成课程与自出题","description":"","frontmatter":{"title":"合成课程与自出题","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/synthetic-curriculum-close.md","filePath":"llm/synthetic-curriculum-close.md","lastUpdated":1791063341000}'),c={name:"llm/synthetic-curriculum-close.md"};function m(p,E,h,u,D,C){const B=n("Mermaid");return l(),d("div",null,[E[2]||(E[2]=t('<h1 id="合成课程与自出题" tabindex="-1">合成课程与自出题 <a class="header-anchor" href="#合成课程与自出题" aria-label="Permalink to &quot;合成课程与自出题&quot;">​</a></h1><div class="epigraph"><p>让模型自己出题，是把课程表的编写权也交给被教的那位；可出题性会替难度做主——它偏爱自己快能会做的题。</p><footer>—— 据 Zelikman 等 STaR；Xu 等 Evol-Instruct 整理</footer></div><p><a href="/llm/rlvr-design-space">上一课</a>把 RLVR 的设计空间切成域、泄露、粒度三轴，其中「域里的题从哪来」留了口子：可验证题目可以人工维护，也可以合成。本课收束本单元：从<a href="/llm/textbook-synthetic">教科书式合成</a>的教师写教材，走到自出题—自排课——出题、解答、排难度由模型闭环完成，并用<a href="/llm/rl-difficulty-curriculum">难度课程</a>与<a href="/llm/dynamic-sampling-rl">动态采样</a>的结论控制难度分布。本单元至此讲完回路的地基，但最危险的一站——没有程序真值时谁来判分——本课不回答：<a href="/llm/self-rewarding-lm">自奖励语言模型</a>那种裁判与选手同一模型的循环依赖，留给下一单元。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>合成课程分两级。教师出题：教科书式合成是原型——大纲定技能轴，教师生成教材与习题，上限是教师分布与大纲覆盖；Evol-Instruct 加加深与换题算子，Meta-Math 式改写自举扩大题量，但都依赖外部大纲与教师。自出题：出题器是当前或旧 checkpoint 的自己，模型给自己出题、解答、再由验证器判分——题源不再受限，但引入一个新的选择环节：出什么题，由谁的目标决定。共同的工程问题是难度分布：组相对 RL 只在中间通过率有信号（全对全错组无梯度），难度课程课的结论是把通过率维持在中间带——合成课程第一次让这个带成为可直接控制的出题参数。<span class="marginnote">术语翻译：「组采样 + 组相对」就是每道题让模型一次采一组答案（如 16 个），组内互相比较算优劣。全对的题和全错的题组内人人一样、没有梯度；只有「有的对有的错」的中间题才提供训练信号——这就是为什么难度窗要卡在中间通过率。</span></p><p><span class="marginnote">难度读数用当前策略的组内通过率，不用教师自评难度：同一道题对教师容易、对学生未必。R1 式配方按通过率过滤题目、丢弃全对全错组，就是这个口径。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>难度分布控制三步。测：每题用当前策略组采样估通过率，作为难度读数——它随训练移动，同一题会从难变中再变易。控：把出题分布校到目标窗（如通过率 \\(0.3\\)–\\(0.7\\)），窗外不丢而是降权或留给下一阶段；动态采样在组内无分叉时过采样补齐，是窗控制的在线版。移：随能力上升右移难度窗，形成课程——这与预训练的数据排序不同：RL 的出题分布本来就该随策略动，动的依据是上一轮通过率。覆盖审计与难度控制并行：按题型、长度、知识点簇检查出题分布，防止难度窗收窄时题型也跟着收窄。</p>',8)),(l(),r(s,null,{default:e(()=>[i(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROP%5B%22%E5%87%BA%E9%A2%98%E5%99%A8%EF%BC%9A%E5%BD%93%E5%89%8D%E6%88%96%E6%97%A7%20checkpoint%22%5D%20--%3E%20SOLVE%5B%22%E8%A7%A3%E9%A2%98%E5%99%A8%EF%BC%9A%E7%BB%84%E9%87%87%E6%A0%B7%22%5D%0A%20%20SOLVE%20--%3E%20RATE%5B%22%E7%BB%84%E5%86%85%E9%80%9A%E8%BF%87%E7%8E%87%EF%BC%9A%E9%9A%BE%E5%BA%A6%E8%AF%BB%E6%95%B0%22%5D%0A%20%20RATE%20--%3E%20CTRL%7B%22%E5%9C%A8%E7%9B%AE%E6%A0%87%E7%AA%97%E5%86%85%EF%BC%9F%22%7D%0A%20%20CTRL%20--%3E%7C%E5%81%8F%E9%AB%98%7C%20HARD%5B%22%E5%8F%B3%E7%A7%BB%EF%BC%9A%E6%9B%B4%E9%9A%BE%E7%9A%84%E9%A2%98%22%5D%0A%20%20CTRL%20--%3E%7C%E5%81%8F%E4%BD%8E%7C%20EASY%5B%22%E9%99%8D%E6%9D%83%E6%88%96%E6%90%81%E7%BD%AE%22%5D%0A%20%20CTRL%20--%3E%7C%E7%AA%97%E5%86%85%7C%20TRAIN%5B%22%E8%BF%9B%E8%AE%AD%E7%BB%83%EF%BC%9A%E7%BB%84%E7%9B%B8%E5%AF%B9%E4%BC%98%E5%8A%BF%22%5D%0A%20%20TRAIN%20--%3E%20UPD%5B%22%E7%AD%96%E7%95%A5%E6%9B%B4%E6%96%B0%22%5D%0A%20%20UPD%20--%3E%20PROP%0A%20%20AUD%5B%22%E8%A6%86%E7%9B%96%E5%AE%A1%E8%AE%A1%EF%BC%9A%E9%A2%98%E5%9E%8B%E4%B8%8E%E7%9F%A5%E8%AF%86%E7%82%B9%E7%B0%87%22%5D%20--%3E%20PROP%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("自出题的新风险是目标漂移：出题分布会漂向「可出且可解」的区域——模板题、短题、模型自家风格的题。漂移是选择压力的产物而非实现错误：过滤器按可解性留题，训练改变解题器，出题器若也被间接选择（经出题质量过滤，或「能产生梯度」的题才被用），整个环节优化的是可训练性而非价值。判据是"),A("a",{href:"/llm/data-flywheel-stop"},"数据飞轮的停止条件"),a("课的仪表：出题侧指标（题目量、通过率分布）还在涨，held-out 真实题的边际增量却在掉——训练分布与真实任务分布脱节了。治理三条：出题器与解题器分离（旧 checkpoint 或不同温度出题，防止题目与解法同源同漂）；真实题型锚（按真实基准的题型分布对出题分布重加权）；出题侧回混（真实题保留固定份额，与"),A("a",{href:"/llm/model-collapse-empirics"},"模型坍缩的实证"),a("课的真实数据回混同一逻辑）。")],-1)),(l(),r(s,null,{default:e(()=>[i(B,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E8%AE%AD%E7%BB%83%E4%B8%8D%E6%96%AD%E6%94%B9%E5%8F%98%E8%A7%A3%E9%A2%98%E5%99%A8%22%5D%20--%3E%20F%5B%22%E8%BF%87%E6%BB%A4%E5%99%A8%E5%8F%AA%E7%95%99%E5%8F%AF%E8%A7%A3%E3%80%81%E6%9C%89%E6%A2%AF%E5%BA%A6%E7%9A%84%E9%A2%98%22%5D%0A%20%20F%20--%3E%20D%5B%22%E5%87%BA%E9%A2%98%E5%88%86%E5%B8%83%E6%BC%82%E5%90%91%E6%A8%A1%E6%9D%BF%E9%A2%98%E4%B8%8E%E8%87%AA%E5%AE%B6%E9%A3%8E%E6%A0%BC%22%5D%0A%20%20D%20--%3E%20S%5B%22held-out%20%E7%9C%9F%E5%AE%9E%E9%A2%98%E7%9A%84%E8%BE%B9%E9%99%85%E5%A2%9E%E9%87%8F%E6%8E%89%E5%A4%B4%22%5D%0A%20%20S%20--%3E%20G1%5B%22%E6%B2%BB%E7%90%86%E4%B8%80%3A%20%E6%97%A7%20checkpoint%20%E5%87%BA%E9%A2%98%2C%20%E5%87%BA%E9%A2%98%E4%B8%8E%E8%A7%A3%E9%A2%98%E5%88%86%E7%A6%BB%22%5D%0A%20%20S%20--%3E%20G2%5B%22%E6%B2%BB%E7%90%86%E4%BA%8C%3A%20%E6%8C%89%E7%9C%9F%E5%AE%9E%E9%A2%98%E5%9E%8B%E5%88%86%E5%B8%83%E9%87%8D%E5%8A%A0%E6%9D%83%22%5D%0A%20%20S%20--%3E%20G3%5B%22%E6%B2%BB%E7%90%86%E4%B8%89%3A%20%E7%9C%9F%E5%AE%9E%E9%A2%98%E4%BF%9D%E7%95%99%E5%9B%BA%E5%AE%9A%E4%BB%BD%E9%A2%9D%E5%9B%9E%E6%B7%B7%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">直觉类比：目标漂移像老师自己出题自己复习——出的题越来越像自己擅长的题型，模拟考分数一路涨，真实考试的题型却没覆盖。held-out 真实题就是「外人出的卷子」，它的边际增量掉头，就是训练分布与真实任务脱节的信号。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课的难度控制假设验证器可信——题的解答对不对仍由程序判；出题与判分都交给模型时，循环依赖进入下一单元的议题。难度窗数值随任务与组大小变，\\(0.3\\)–\\(0.7\\) 是常用口径不是常数。出题器扩到开放域（无验证器的自由出题）超出本单元，那里的判分问题正是下一单元第一课的入口。<span class="marginnote">常见误区：初学者容易把「通过率 0.3–0.7」当万能常数照抄。它随组大小、任务域、奖励粒度变——组越大极端组越少、可用的中间带越宽，数学与代码的最优窗也不同。课程参数要靠自己的代理实验校，不是抄论文数字。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>合成课程两级：教师出题（上限是教师与大纲）、自出题（题源开放但引入选择环节）。</li><li>难度读数用组内通过率，目标窗控制并随训练右移；覆盖审计与难度控制并行。</li><li>目标漂移：可出可解区域吃掉训练分布；判据是 held-out 边际增量掉头。</li><li>治理：出题与解题分离、真实题型重加权、出题侧回混。</li><li>出处：Zelikman 等 STaR；Xu 等 Evol-Instruct；Yu 等 Meta-Math；DeepSeek-AI R1 的难度过滤；Muennighoff 等 s1 的选题口径。</li></ul>',5))])}const T=o(c,[["render",m]]);export{F as __pageData,T as default};
